      "sexo": "All",
      "formulaciones": "Oral > Solid > dispersible tablet: 100 mg ; 125 mg ; 250 mg ; 400 mg ; 500 mg Oral > Solid > tablet: 90 mg ; 180 mg ; 360 mg",
      "notas": "",
